-- FAA NOTAM + WXL weather correlation overlay — emit_notam_wxl.py
-- Generated: 2026-06-26T15:22:11Z

ALTER SESSION SET CONTAINER = FREEPDB1;
ALTER SESSION SET CURRENT_SCHEMA = nas_sim;

-- Scenario NOTAMs (FAA-format, linked to seeded equipment/runways)

MERGE INTO notam t USING (SELECT '31000001-0001-4001-8001-000000000001' AS notam_id, '6/234' AS notam_number, f.facility_id, e.equipment_id, r.runway_id, 'DOMESTIC' AS classification, 'NAV' AS feature, 'ILS RWY 13 GS U/S. LOC U/S. AUTOLAND NA. VOR/DME RWY 13 APCH NA.' AS notam_text, TIMESTAMP '2026-06-23 08:00:00' AS effective_start_utc, TIMESTAMP '2026-06-24 06:00:00' AS effective_end_utc, 'Y' AS is_active, q'[{"source":"faa","faaBaseline":{"nasrCycle":"2026-06-11","source":"scenario","faaFormat":true,"scenarioNote":"Primary ILS outage narrative"}}]' AS metadata_json FROM facility f LEFT JOIN equipment e ON e.facility_id = f.facility_id AND e.identifier = 'ILS-13-DSM' LEFT JOIN runway r ON r.facility_id = f.facility_id AND r.designator = '13/31' WHERE f.facility_code = 'KDSM') s ON (t.notam_id = s.notam_id) WHEN NOT MATCHED THEN INSERT (notam_id, notam_number, facility_id, equipment_id, runway_id, classification, feature, notam_text, effective_start_utc, effective_end_utc, is_active, metadata_json) VALUES (s.notam_id, s.notam_number, s.facility_id, s.equipment_id, s.runway_id, s.classification, s.feature, s.notam_text, s.effective_start_utc, s.effective_end_utc, s.is_active, s.metadata_json);
MERGE INTO notam t USING (SELECT '31000002-0001-4001-8001-000000000002' AS notam_id, '6/235' AS notam_number, f.facility_id, e.equipment_id, r.runway_id, 'DOMESTIC' AS classification, 'RWY' AS feature, 'RWY 13 RESTRICTED. ILS GS U/S. USE RWY 05/23 OR VOR APCH RWY 31.' AS notam_text, TIMESTAMP '2026-06-23 08:00:00' AS effective_start_utc, NULL AS effective_end_utc, 'Y' AS is_active, q'[{"source":"faa","faaBaseline":{"nasrCycle":"2026-06-11","source":"scenario","faaFormat":true}}]' AS metadata_json FROM facility f LEFT JOIN equipment e ON 1 = 0 LEFT JOIN runway r ON r.facility_id = f.facility_id AND r.designator = '13/31' WHERE f.facility_code = 'KDSM') s ON (t.notam_id = s.notam_id) WHEN NOT MATCHED THEN INSERT (notam_id, notam_number, facility_id, equipment_id, runway_id, classification, feature, notam_text, effective_start_utc, effective_end_utc, is_active, metadata_json) VALUES (s.notam_id, s.notam_number, s.facility_id, s.equipment_id, s.runway_id, s.classification, s.feature, s.notam_text, s.effective_start_utc, s.effective_end_utc, s.is_active, s.metadata_json);
MERGE INTO notam t USING (SELECT '31000003-0001-4001-8001-000000000003' AS notam_id, 'ORD-WS-061' AS notam_number, f.facility_id, e.equipment_id, r.runway_id, 'DOMESTIC' AS classification, 'AIRSPACE' AS feature, 'LLWS ALERT. WIND SHEAR ALONG FINAL RWY 10L/28R. PILOTS USE CAUTION.' AS notam_text, TIMESTAMP '2026-06-23 13:00:00' AS effective_start_utc, TIMESTAMP '2026-06-23 20:00:00' AS effective_end_utc, 'Y' AS is_active, q'[{"source":"faa","faaBaseline":{"nasrCycle":"2026-06-11","source":"scenario","faaFormat":true,"llwas":true}}]' AS metadata_json FROM facility f LEFT JOIN equipment e ON 1 = 0 LEFT JOIN runway r ON 1 = 0 WHERE f.facility_code = 'KORD') s ON (t.notam_id = s.notam_id) WHEN NOT MATCHED THEN INSERT (notam_id, notam_number, facility_id, equipment_id, runway_id, classification, feature, notam_text, effective_start_utc, effective_end_utc, is_active, metadata_json) VALUES (s.notam_id, s.notam_number, s.facility_id, s.equipment_id, s.runway_id, s.classification, s.feature, s.notam_text, s.effective_start_utc, s.effective_end_utc, s.is_active, s.metadata_json);

-- WXL weather reporting station correlation on weather_event rows
UPDATE weather_event SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"nasrCycle":"2026-06-11","wxStationId":"DSM","wxServices":"IA     958SFD FT METAR NOTAM SA SPECI TAF UA","latFormatted":"4132023N","lonFormatted":"09339471W","correlationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE weather_event_id = '27000001-0001-4001-8001-000000000001';
UPDATE weather_event SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"nasrCycle":"2026-06-11","wxStationId":"MSP","wxServices":"MN     842EFD FT METAR NOTAM SA SPECI TAF UA","latFormatted":"4452551N","lonFormatted":"09313184W","correlationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE weather_event_id = '27000002-0001-4001-8001-000000000002';
UPDATE weather_event SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"nasrCycle":"2026-06-11","wxStationId":"ORD","wxServices":"GO                                 IL     680EFT NOTAM SA UA","latFormatted":"4158369N","lonFormatted":"08754293W","correlationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE weather_event_id = '27000003-0001-4001-8001-000000000003';

