UPDATE facility SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"wxStationId":"DSM","wxServices":"IA     958SFD FT METAR NOTAM SA SPECI TAF UA","wxCorrelationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE facility_code = 'KDSM';
UPDATE facility SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"wxStationId":"MKE","wxServices":"WI     728EFT METAR NOTAM SA SPECI TAF UA","wxCorrelationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE facility_code = 'KMKE';
UPDATE facility SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"wxStationId":"MLI","wxServices":"IL     590SFT METAR NOTAM SA SPECI TAF UA","wxCorrelationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE facility_code = 'KMLI';
UPDATE facility SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"wxStationId":"MSP","wxServices":"MN     842EFD FT METAR NOTAM SA SPECI TAF UA","wxCorrelationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE facility_code = 'KMSP';
UPDATE facility SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"wxStationId":"OMA","wxServices":"NE     985SFD FT NOTAM SA UA","wxCorrelationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE facility_code = 'KOMA';
UPDATE facility SET metadata_json = JSON_MERGEPATCH(COALESCE(metadata_json, TO_CLOB('{}')), q'[{"source":"faa","faaBaseline":{"wxStationId":"ORD","wxServices":"GO                                 IL     680EFT NOTAM SA UA","wxCorrelationSource":"NASR-WXL"}}]'), updated_at = SYSTIMESTAMP WHERE facility_code = 'KORD';

COMMIT;
